mapper.select:
SELECT ID, EMAIL, NICKNAME, NAME, PASSWORD_HASH,
       AUTH_PROVIDER, SOCIAL_ID, ROLE, IMG, CREATED_AT, UPDATED_AT
FROM USER WHERE EMAIL = #{email}

SELECT ID, EMAIL, NICKNAME, NAME, PASSWORD_HASH,
       AUTH_PROVIDER, SOCIAL_ID, ROLE, IMG, CREATED_AT, UPDATED_AT
FROM USER WHERE ID = #{id}

SELECT ID, EMAIL, NICKNAME, NAME, PASSWORD_HASH,
       AUTH_PROVIDER, SOCIAL_ID, ROLE, IMG, CREATED_AT, UPDATED_AT
FROM USER
WHERE AUTH_PROVIDER = #{authProvider}
  AND SOCIAL_ID = #{socialId}
